package com.korlebu.config;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.concurrent.ConcurrentHashMap; import java.util.concurrent.atomic.AtomicInteger;
@Component
public class RateLimitFilter implements Filter { @Value("${app.rate-limit.requests-per-minute:120}") private int limit; private final ConcurrentHashMap<String,Window> windows=new ConcurrentHashMap<>(); public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req; if(!r.getRequestURI().startsWith("/api/")){chain.doFilter(req,res);return;} String key=r.getRemoteAddr(); Window w=windows.computeIfAbsent(key,k->new Window()); synchronized(w){long now=System.currentTimeMillis();if(now-w.start>60000){w.start=now;w.count.set(0);}if(w.count.incrementAndGet()>limit){((HttpServletResponse)res).setStatus(HttpStatus.TOO_MANY_REQUESTS.value());return;}}chain.doFilter(req,res);} static class Window{long start=System.currentTimeMillis();AtomicInteger count=new AtomicInteger();}}
